/** 历史硬化：脱敏无原文 + 轮转 200/50 + root 三形态 + 单会话清空（mkdtemp 隔离，全离线）。
 *
 * 守的是 history/redact+hash+entry+service：把掩码删一项、轮转改大、basename 误存全路径、
 * 删除放宽到整库任一改动，本文件必红。落盘仅 mkdtempSync 目录。
 */
import { mkdtempSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import type { HistoryEntry } from "../../src/shared/interface.ts";
import type { HistoryDeps } from "../../src/server/history/deps.ts";
import { assembleEntry } from "../../src/server/history/impl/entry.ts";
import { resolveRootHash, rootDisplayOf, rootHashOf } from "../../src/server/history/impl/hash.ts";
import { redactSnippet } from "../../src/server/history/impl/redact.ts";
import {
  appendEntry,
  deleteSession,
  historyFile,
  queryEntries,
} from "../../src/server/history/impl/service.ts";
import {
  atomicWrite0600Sync,
  ensureDir0700,
  listFilesSync,
  mtimeMs,
  readTextSync,
  removeFileSync,
} from "../../src/server/store/impl/io.ts";

function deps(): HistoryDeps {
  return {
    io: {
      readTextSync,
      atomicWrite0600Sync,
      listFilesSync,
      mtimeMs,
      removeFileSync,
      ensureDir0700,
    },
    logger: { warn: () => {} },
  };
}
function tempHome(): string {
  return mkdtempSync(join(tmpdir(), "jev-hist-hard-"));
}
function entry(sessionId: string, extra: Partial<HistoryEntry> = {}): HistoryEntry {
  return {
    ts: Date.now(),
    rootHash: rootHashOf("/work/proj"),
    rootDisplay: "proj",
    sessionId,
    presetId: "general",
    templateVersion: 1,
    stateHash: "abc",
    snippetRedacted: "hello",
    lang: "en",
    truncated: false,
    originalLength: 5,
    resultKind: "choice",
    choice: "A",
    confidence: 0.5,
    tier: "high",
    automation: "auto",
    provider: "official",
    latencyMs: 3,
    ...extra,
  };
}

describe("脱敏无密钥原文", () => {
  it.each([
    "key sk-Abcdef12345678 end",
    "token AKIAIOSFODNN7EXAMPLE here",
    "ghp_abcdefgh12345678 leak",
    "xoxb-1234-abcd token",
    "xoxp-secret-value here",
    "-----BEGIN PRIVATE KEY-----\nMIIB\n-----END PRIVATE KEY-----",
    "api_key: hunter2-value",
    "password=hunter2",
    "secret: topsecret123",
  ])("掩码 %s 无原文且 ≤200 字", (raw) => {
    const out = redactSnippet(raw);
    expect(out).not.toContain("AKIAIOSFODNN7EXAMPLE");
    expect(out).not.toContain("hunter2");
    expect(out).not.toContain("topsecret123");
    expect(Array.from(out).length).toBeLessThanOrEqual(200);
    // 具体掩码标记：至少原文被替换（长度变化或含 ***)。
    expect(out === raw).toBe(false);
  });
  it("超长先脱敏后截断：掩码不断半", () => {
    const raw = "prefix sk-Abcdef12345678 " + "x".repeat(500);
    const out = redactSnippet(raw);
    expect(out).not.toContain("sk-Abcdef12345678");
    expect(Array.from(out).length).toBeLessThanOrEqual(200);
  });
  it("长 PEM 整体掩码：超 200 字密钥体无残留", () => {
    const body = "MIIEvQIBADANBgkqhkiG9w0BAQEFAASC".repeat(20);
    const raw = "-----BEGIN PRIVATE KEY-----\n" + body + "\n-----END PRIVATE KEY-----";
    expect(raw.length).toBeGreaterThan(600);
    const out = redactSnippet(raw);
    expect(out).not.toContain("MIIEvQ");
    expect(out).not.toContain("PRIVATE KEY");
    expect(Array.from(out).length).toBeLessThanOrEqual(200);
  });
  it("assembleEntry 永不带密钥字段：原文不出境存证", () => {
    const secret = "sk-Abcdef12345678";
    const e = assembleEntry(
      "/work/proj",
      "s-1",
      {
        presetId: "general",
        text: secret,
        lang: "en",
        truncated: false,
        originalLength: 17,
        resultKind: "choice",
        questions: [{ id: "q1", text: "Pick one.", kind: "choice", options: ["A", secret] }],
        choice: "A",
        confidence: 1,
        tier: "high",
        automation: "auto",
        latencyMs: 1,
        precheckHit: false,
      },
      7,
    );
    expect(JSON.stringify(e)).not.toContain(secret);
    expect(e).toMatchObject({ provider: "official", templateVersion: 1, sessionId: "s-1", ts: 7 });
    expect(e.questions).toHaveLength(1);
    expect(e.questions?.[0]?.options?.[1]).toBe("***");
    expect(JSON.stringify(e)).not.toContain(secret);
    expect(e.rootDisplay).toBe("proj");
    expect(e.rootHash).toBe(rootHashOf("/work/proj"));
  });
  it("precheck 命中即 snippet 全掩码（S1-A）", () => {
    const e = assembleEntry(
      "/work/proj",
      "s-1",
      {
        presetId: "general",
        text: "x".repeat(500),
        lang: "en",
        truncated: true,
        originalLength: 500,
        resultKind: "local-precheck",
        questions: [],
        choice: "human",
        confidence: 1,
        tier: "none",
        automation: "manual",
        latencyMs: 0,
        precheckHit: true,
      },
      9,
    );
    expect(e.snippetRedacted).toBe("***");
  });
});

describe("轮转 200/50 精确", () => {
  it("每会话只留末尾 200 条（204 为首）", () => {
    const home = tempHome();
    for (let i = 0; i < 205; i += 1)
      appendEntry(home, entry("s-1", { ts: i }), { perSession: 200, totalSessions: 50 }, deps());
    const got = queryEntries(home, { sessionId: "s-1", limit: 500 }, deps());
    expect(got).toHaveLength(200);
    expect(got[0]?.ts).toBe(204);
    expect(got[got.length - 1]?.ts).toBe(5);
  });
  it("总会话超 50 按 mtime 淘汰最旧（手写假 io 确定性）", () => {
    const files = new Map<string, string>();
    const mtimes = new Map<string, number>();
    let clock = 1000;
    const fake: HistoryDeps = {
      logger: { warn: () => {} },
      io: {
        readTextSync: (f: string) =>
          files.has(f)
            ? { ok: true as const, text: files.get(f) as string }
            : { ok: false as const },
        atomicWrite0600Sync: (f: string, t: string) => {
          files.set(f, t);
          mtimes.set(f, (clock += 10));
        },
        listFilesSync: (dir: string) => {
          const prefix = dir.endsWith("/") ? dir : dir + "/";
          const children = new Set<string>();
          for (const f of files.keys()) {
            if (f.startsWith(prefix)) {
              const rest = f.slice(prefix.length);
              const slash = rest.indexOf("/");
              children.add(slash === -1 ? rest : rest.slice(0, slash));
            }
          }
          return [...children];
        },
        mtimeMs: (f: string) => mtimes.get(f) ?? -1,
        removeFileSync: (f: string) => {
          files.delete(f);
          mtimes.delete(f);
        },
        ensureDir0700: () => {},
      },
    };
    const home = "/fake-home";
    for (let i = 0; i < 52; i += 1)
      appendEntry(
        home,
        entry("s-" + String(i), { ts: i }),
        { perSession: 200, totalSessions: 50 },
        fake,
      );
    const got = queryEntries(home, {}, fake);
    const sessions = new Set(got.map((e) => e.sessionId));
    expect(sessions.size).toBe(50);
    expect(sessions.has("s-0")).toBe(false);
    expect(sessions.has("s-1")).toBe(false);
    expect(sessions.has("s-51")).toBe(true);
  });
});

describe("root 三形态过滤 + 单会话清空", () => {
  it("路径/hash/basename 三形态同命中；空即全量", () => {
    const home = tempHome();
    appendEntry(home, entry("s-9"), { perSession: 200, totalSessions: 50 }, deps());
    expect(queryEntries(home, { root: "/work/proj" }, deps())).toHaveLength(1);
    expect(queryEntries(home, { root: rootHashOf("/work/proj") }, deps())).toHaveLength(1);
    expect(queryEntries(home, { root: "proj" }, deps())).toHaveLength(1);
    expect(queryEntries(home, {}, deps())).toHaveLength(1);
    expect(queryEntries(home, { root: "/other" }, deps())).toHaveLength(0);
  });
  it("limit 钳制 1..500", () => {
    const home = tempHome();
    for (let i = 0; i < 5; i += 1)
      appendEntry(home, entry("s-l", { ts: i }), { perSession: 200, totalSessions: 50 }, deps());
    expect(queryEntries(home, { sessionId: "s-l", limit: 2 }, deps())).toHaveLength(2);
    expect(queryEntries(home, { sessionId: "s-l", limit: 9999 }, deps())).toHaveLength(5);
  });
  it("删除仅单会话：缺 root/sessionId 即 400；异会话不受影响", () => {
    const home = tempHome();
    appendEntry(home, entry("s-a"), { perSession: 200, totalSessions: 50 }, deps());
    appendEntry(home, entry("s-b"), { perSession: 200, totalSessions: 50 }, deps());
    expect(() => deleteSession(home, { root: "/work/proj" }, deps())).toThrow();
    expect(() => deleteSession(home, { sessionId: "s-a" }, deps())).toThrow();
    expect(() => deleteSession(home, { root: "", sessionId: "" }, deps())).toThrow();
    expect(deleteSession(home, { root: "/work/proj", sessionId: "s-a" }, deps())).toMatchObject({
      deleted: true,
    });
    expect(queryEntries(home, { sessionId: "s-a" }, deps())).toHaveLength(0);
    expect(queryEntries(home, { sessionId: "s-b" }, deps())).toHaveLength(1);
    expect(deleteSession(home, { root: "/work/proj", sessionId: "nope" }, deps())).toMatchObject({
      deleted: false,
    });
  });
  it("非法 sessionId 形状即抛（含路径穿越）", () => {
    expect(() => historyFile("/tmp/h", rootHashOf("/a"), "../evil")).toThrow();
    expect(() => historyFile("/tmp/h", "zzz", "s-1")).toThrow();
    expect(rootDisplayOf("/a/b/proj")).toBe("proj");
    expect(resolveRootHash(rootHashOf("/a/b"))).toBe(rootHashOf("/a/b"));
  });
});

/** 密钥硬化：ENV 正则 + 全大写形状 + PUT 互斥 + GET 掩码 + 日志无原文（mkdtemp 隔离，全离线）。
 *
 * 守的是 config/model.validatePutBody + service.savePatch/toMaskedConfig/resolveApiKey：
 * 把正则放宽、互斥删掉、掩码漏原文任一改动，本文件必红。落盘仅 mkdtempSync 目录。
 */
import { mkdtempSync, readFileSync, statSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import { validatePutBody } from "../../src/server/config/impl/model.ts";
import {
  loadState,
  resolveApiKey,
  savePatch,
  toMaskedConfig,
} from "../../src/server/config/impl/service.ts";
import type { ConfigDeps } from "../../src/server/config/deps.ts";
import { atomicWrite0600Sync, readJsonSync, readTextSync } from "../../src/server/store/impl/io.ts";
import { keyShapeCategory } from "../../src/shared/contract.ts";

function depsWithLog(seen: string[]): ConfigDeps {
  return {
    io: { readJsonSync, readTextSync, atomicWrite0600Sync },
    logger: {
      warn: (m: string) => {
        seen.push(m);
      },
    },
  };
}
function plainDeps(): ConfigDeps {
  return { io: { readJsonSync, readTextSync, atomicWrite0600Sync }, logger: { warn: () => {} } };
}
function tempHome(): string {
  return mkdtempSync(join(tmpdir(), "jev-keys-"));
}
const PLAINTEXT = "Abcdefgh12345678";

describe("ENV 引用正则", () => {
  it("合法：大写开头 2..64 位 A-Z0-9_", () => {
    for (const good of ["JEV_API_KEY", "A1", "AKIAIOSFODNN7EXAMPLE", "JEV_TEST_KEY_X1"]) {
      expect(validatePutBody({ apiKeyRef: good }).ok).toBe(true);
    }
    expect(validatePutBody({ apiKeyRef: "A".repeat(64) }).ok).toBe(true);
  });
  it("非法：小写/中文/空串/数字开头/下划线开头/连字符/超长", () => {
    for (const bad of [
      "lower",
      "jev_key",
      "密钥",
      "",
      "a",
      "1ABC",
      "_ABC",
      "JEV-KEY",
      "A".repeat(65),
    ]) {
      const r = validatePutBody({ apiKeyRef: bad });
      expect(r.ok).toBe(false);
    }
  });
  it("null 即清除引用（合法补丁）", () => {
    const r = validatePutBody({ apiKeyRef: null });
    expect(r.ok).toBe(true);
    if (r.ok) expect(r.patch.apiKeyRef).toBe(null);
  });
});

describe("明文形状与全大写缺口", () => {
  it("形状类别：empty/too-short/charset 精确", () => {
    expect(keyShapeCategory("")).toBe("empty");
    expect(keyShapeCategory("abc")).toBe("too-short");
    expect(keyShapeCategory("1234567890123456")).toBe("charset");
    expect(keyShapeCategory("Abcdefgh12345678!")).toBe("charset");
    expect(keyShapeCategory(PLAINTEXT)).toBe(null);
  });
  it("全大写长串拒收（P0 硬化，阈值 20）", () => {
    // src ALL_CAPS_REJECT_MIN_LEN=20：≥20 位全大写字母数字混合或 AKIA/ASIA 前缀即 charset；
    // 16 位全大写无前缀可辨仍放行（与 src 对齐，不从严）。
    expect(keyShapeCategory("AKIAIOSFODNN7EXAMPLE")).toBe("charset");
    expect(keyShapeCategory("ABCDEFGHIJKLMNOP")).toBe(null);
    const r = validatePutBody({ apiKeyPlaintext: "AKIAIOSFODNN7EXAMPLE", confirm: true });
    expect(r.ok).toBe(false);
    if (!r.ok) {
      expect(r.failure.errorCode).toBe("INVALID_KEY_SHAPE");
      expect(r.failure.category).toBe("charset");
      expect(JSON.stringify(r.failure)).not.toContain("AKIAIOSFODNN7EXAMPLE");
    }
  });
  it("形状拒收仅回类别、无原文", () => {
    const short = validatePutBody({ apiKeyPlaintext: "abc", confirm: true });
    expect(short.ok).toBe(false);
    if (!short.ok) {
      expect(short.failure.errorCode).toBe("INVALID_KEY_SHAPE");
      expect(short.failure.category).toBe("too-short");
      expect(JSON.stringify(short.failure)).not.toContain("abc");
    }
  });
  it("短密钥无 confirm 仍 400 形状错（形状先于确认）", () => {
    const short = validatePutBody({ apiKeyPlaintext: "abc" });
    expect(short.ok).toBe(false);
    if (!short.ok) expect(short.failure.category).toBe("too-short");
  });
  it("明文免二次确认：缺 confirm 即成功", () => {
    const r = validatePutBody({ apiKeyPlaintext: PLAINTEXT });
    expect(r.ok).toBe(true);
    expect(validatePutBody({ apiKeyPlaintext: PLAINTEXT, confirm: true }).ok).toBe(true);
  });
  it("confirm 显式 false 同样忽略；孤 confirm 无害空补丁", () => {
    const allowed = validatePutBody({ apiKeyPlaintext: PLAINTEXT, confirm: false });
    expect(allowed.ok).toBe(true);
    const lone = validatePutBody({ confirm: true });
    expect(lone.ok).toBe(true);
    if (lone.ok) expect(lone.patch).toEqual({});
  });
});

describe("M1 合并语义：presets 按 id 合并，history 浅合并", () => {
  it("presets 子集补丁只改命中项（secret-leak 不复活）", () => {
    const home = tempHome();
    const checked = validatePutBody({
      presets: [{ id: "general", enabled: false, automationCap: 2 }],
    });
    expect(checked.ok).toBe(true);
    if (!checked.ok) return;
    const saved = savePatch(home, checked.patch, plainDeps());
    expect(saved.config.presets.find((p) => p.id === "general")?.enabled).toBe(false);
    expect(saved.config.presets.find((p) => p.id === "secret-leak")?.enabled).toBe(false);
    expect(saved.config.presets.find((p) => p.id === "plan-review")?.enabled).toBe(true);
    expect(saved.config.presets).toHaveLength(5);
  });
  it("history 部分补丁保留未提键", () => {
    const home = tempHome();
    const checked = validatePutBody({ history: { perSession: 100 } });
    expect(checked.ok).toBe(true);
    if (!checked.ok) return;
    const saved = savePatch(home, checked.patch, plainDeps());
    expect(saved.config.history).toMatchObject({ perSession: 100, totalSessions: 50 });
  });
});

describe("PUT 双轨互斥 + GET 掩码 + 日志无原文", () => {
  it("同体双轨即 MUTUALLY_EXCLUSIVE", () => {
    const r = validatePutBody({
      apiKeyRef: "JEV_API_KEY",
      apiKeyPlaintext: PLAINTEXT,
      confirm: true,
    });
    expect(r.ok).toBe(false);
    if (!r.ok) expect(r.failure.errorCode).toBe("MUTUALLY_EXCLUSIVE");
  });
  it("PUT 落盘后 GET 掩码：config/掩码面均无原文", () => {
    const home = tempHome();
    const checked = validatePutBody({ apiKeyPlaintext: PLAINTEXT, confirm: true });
    expect(checked.ok).toBe(true);
    if (!checked.ok) return;
    const saved = savePatch(home, checked.patch, plainDeps());
    expect(saved.config.connection.hasPlaintextKey).toBe(true);
    const masked = toMaskedConfig(saved);
    expect(JSON.stringify(masked)).not.toContain(PLAINTEXT);
    expect(masked.connection.hasPlaintextKey).toBe(true);
    expect(masked.connection.apiKeyRef).toBe(undefined);
    const diskConfig = readFileSync(
      join(home, "@wingsky-1/dsh-decision-gateway", "config.json"),
      "utf8",
    );
    expect(diskConfig).not.toContain(PLAINTEXT);
    const reloaded = toMaskedConfig(loadState(home, plainDeps()));
    expect(JSON.stringify(reloaded)).not.toContain(PLAINTEXT);
  });
  it("ENV 引用优先于明文；切轨即折叠清空 secrets", () => {
    const home = tempHome();
    const secret = validatePutBody({ apiKeyPlaintext: PLAINTEXT, confirm: true });
    expect(secret.ok).toBe(true);
    if (!secret.ok) return;
    savePatch(home, secret.patch, plainDeps());
    const ref = validatePutBody({ apiKeyRef: "JEV_TEST_KEY_X1" });
    expect(ref.ok).toBe(true);
    if (!ref.ok) return;
    const saved = savePatch(home, ref.patch, plainDeps());
    const resolved = resolveApiKey(saved, { JEV_TEST_KEY_X1: "EnvSecretValue12345" }, plainDeps());
    expect(resolved).toMatchObject({ key: "EnvSecretValue12345", source: "env" });
    expect(resolveApiKey(saved, {}, plainDeps()).source).toBe("none");
    const secretsDisk = readFileSync(
      join(home, "@wingsky-1/dsh-decision-gateway", "secrets.json"),
      "utf8",
    );
    expect(secretsDisk).not.toContain(PLAINTEXT);
  });
  it("落盘权限 0600/0700（R8，POSIX）", () => {
    if (process.platform === "win32") return;
    const home = tempHome();
    const checked = validatePutBody({ apiKeyPlaintext: PLAINTEXT, confirm: true });
    expect(checked.ok).toBe(true);
    if (!checked.ok) return;
    savePatch(home, checked.patch, plainDeps());
    const dir = join(home, "@wingsky-1/dsh-decision-gateway");
    expect(statSync(dir).mode & 0o777).toBe(0o700);
    expect(statSync(join(dir, "config.json")).mode & 0o777).toBe(0o600);
    expect(statSync(join(dir, "secrets.json")).mode & 0o777).toBe(0o600);
  });
  it("日志永无密钥原文", () => {
    const home = tempHome();
    const seen: string[] = [];
    const checked = validatePutBody({ apiKeyPlaintext: PLAINTEXT, confirm: true });
    expect(checked.ok).toBe(true);
    if (!checked.ok) return;
    savePatch(home, checked.patch, depsWithLog(seen));
    // 手改坏形状明文：解析视同无 key 并告警，告警不得带原文。
    const state = loadState(home, plainDeps());
    const BAD_PLAINTEXT = "XxBadShort";
    const tampered = { ...state, plaintext: BAD_PLAINTEXT };
    const out = resolveApiKey(tampered, {}, depsWithLog(seen));
    expect(out.source).toBe("none");
    expect(seen.join("\n")).not.toContain(PLAINTEXT);
    expect(seen.join("\n")).not.toContain(BAD_PLAINTEXT);
  });
});

/** 本地预检不离境：全密形命中即 local-precheck 且 fetch 零调用（全离线；全局 fetch 桩为例外，直连默认 fetch 旁路验证）。
 *
 * 守的是 tools/precheck.localPrecheckHit + service.decide 的预检短路：把任一密形删掉、
 * 短路移到密钥之后、忘记计数 fetch，本文件必红。fetch 经注入计数，落盘无。
 */
import { describe, expect, it } from "vitest";
import { decide } from "../../src/server/tools/impl/service.ts";
import { localPrecheckHit } from "../../src/server/tools/impl/precheck.ts";
import type { DecideDeps } from "../../src/server/tools/deps.ts";

const CONNECTION = {
  timeoutMs: 8000,
  maxConcurrency: 4,
  truncBudget: 32000,
  hasPlaintextKey: false,
} as const;

function baseDeps(over: Partial<DecideDeps> = {}): DecideDeps {
  return {
    logger: { warn: () => {} },
    connection: { ...CONNECTION },
    isEnabled: () => true,
    capOf: () => 2,
    resolveKey: () => ({ key: "Abcdefgh12345678", source: "env" as const }),
    root: "/tmp/proj",
    sessionId: "sess-1",
    signal: new AbortController().signal,
    ...over,
  };
}

const SECRETS: readonly string[] = [
  "key sk-Abcdef12345678 here",
  "token AKIAIOSFODNN7EXAMPLE here",
  "ghp_abcdefgh12345678 leak",
  "xoxb-1234-abcd token",
  "-----BEGIN PRIVATE KEY-----\nMIIB\n-----END PRIVATE KEY-----",
  "api_key: hunter2-value",
  "password=hunter2",
  "secret: topsecret123",
];

describe("secret-leak 本地预检命中不离境", () => {
  it("残缺不命中、残头命中（打红点：{8,}/{16}/+/[:=] 量词）", () => {
    for (const frag of [
      "sk-",
      "sk-Abc12",
      "AKIA",
      "ghp_",
      "xoxb-",
      "password",
      "password=",
      "api_key: ",
    ]) {
      expect(localPrecheckHit(frag)).toBe(false);
    }
    expect(localPrecheckHit("-----BEGIN PRIVATE KEY-----")).toBe(true);
    expect(localPrecheckHit("-----BEGIN RSA PRIVATE KEY-----")).toBe(true);
  });
  it("全密形命中；干净文本不命中", () => {
    for (const raw of SECRETS) expect(localPrecheckHit(raw)).toBe(true);
    expect(localPrecheckHit("today is sunny")).toBe(false);
    expect(localPrecheckHit("hello world")).toBe(false);
  });
  it.each(SECRETS)("命中 %s 即 local-precheck 且 fetch 零调用", async (secretText) => {
    let calls = 0;
    const events: unknown[] = [];
    const out = await decide(
      {
        preset_id: "general",
        state: { text: "prefix " + secretText + " suffix", lang: "en" },
        questions_override: [{ id: "q1", text: "Pick one.", kind: "choice", options: ["A", "B"] }],
      },
      baseDeps({
        fetchImpl: async () => {
          calls += 1;
          return { status: 200, text: "{}" };
        },
        recordEvent: (e) => {
          events.push(e);
        },
      }),
    );
    expect(calls).toBe(0);
    expect(out).toMatchObject({
      ok: true,
      provider: "official",
      appliedSource: "local-precheck",
      tier: "none",
      automation: "manual",
    });
    expect(events).toHaveLength(1);
  });
  it("禁用预设优先于预检：secret-leak 关闭即 PRESET_DISABLED（不走 local-precheck）", async () => {
    let calls = 0;
    const out = await decide(
      {
        preset_id: "secret-leak",
        state: { text: "my sk-Abcdef12345678 leak", lang: "en" },
        questions_override: [{ id: "q1", text: "Pick one.", kind: "choice", options: ["A", "B"] }],
      },
      baseDeps({
        isEnabled: (id) => id !== "secret-leak",
        fetchImpl: async () => {
          calls += 1;
          return { status: 200, text: "{}" };
        },
      }),
    );
    expect(calls).toBe(0);
    expect(out.ok).toBe(false);
    if (!out.ok) expect(out.error.errorCode).toBe("PRESET_DISABLED");
  });
  it("全局 fetch 桩亦零调用：预检短路不经过默认 fetch", async () => {
    const prev = (globalThis as unknown as { fetch?: unknown }).fetch;
    let globalCalls = 0;
    (globalThis as unknown as { fetch: unknown }).fetch = async () => {
      globalCalls += 1;
      throw new Error("must not egress");
    };
    try {
      let calls = 0;
      const out = await decide(
        {
          preset_id: "general",
          state: { text: "leak sk-Abcdef12345678", lang: "en" },
          questions_override: [
            { id: "q1", text: "Pick one.", kind: "choice", options: ["A", "B"] },
          ],
        },
        baseDeps({
          fetchImpl: async () => {
            calls += 1;
            return { status: 200, text: "{}" };
          },
        }),
      );
      expect(calls).toBe(0);
      expect(globalCalls).toBe(0);
      expect(out).toMatchObject({ ok: true, appliedSource: "local-precheck" });
    } finally {
      if (prev === undefined) delete (globalThis as unknown as { fetch?: unknown }).fetch;
      else (globalThis as unknown as { fetch: unknown }).fetch = prev;
    }
  });
  it("无 key 与禁用同样不触网且包络结构化", async () => {
    let calls = 0;
    const noKey = await decide(
      {
        preset_id: "general",
        state: { text: "hi", lang: "en" },
        questions_override: [{ id: "q1", text: "Pick one.", kind: "choice", options: ["A", "B"] }],
      },
      baseDeps({
        resolveKey: () => ({ key: undefined, source: "none" as const }),
        fetchImpl: async () => {
          calls += 1;
          return { status: 200, text: "{}" };
        },
      }),
    );
    expect(calls).toBe(0);
    expect(noKey.ok).toBe(false);
    if (!noKey.ok) {
      expect(noKey.error.errorCode).toBe("NO_KEY");
      expect(typeof noKey.error.category).toBe("string");
    }
  });
});

/** config 域单测（纯逻辑 + mkdtempSync 落盘隔离，全程离线）。 */
import { mkdtempSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import {
  buildDefaultConfig,
  normalizeLoadedConfig,
  validatePutBody,
} from "../../src/server/config/impl/model.ts";
import {
  configFile,
  decisionGatewayHome,
  presetsFile,
  secretsFile,
  versionFile,
} from "../../src/server/config/impl/paths.ts";
import {
  readStoredVersion,
  resolveApiKey,
  savePatch,
  toMaskedConfig,
  writeStoredVersion,
} from "../../src/server/config/impl/service.ts";
import type { ConfigDeps } from "../../src/server/config/deps.ts";
import { atomicWrite0600Sync, readJsonSync, readTextSync } from "../../src/server/store/impl/io.ts";

function deps(): ConfigDeps {
  return { io: { readJsonSync, readTextSync, atomicWrite0600Sync }, logger: { warn: () => {} } };
}

function tempHome(): string {
  return mkdtempSync(join(tmpdir(), "jev-config-"));
}

describe("默认值", () => {
  it("version=1 且 secret-leak 默认关闭", () => {
    const config = buildDefaultConfig();
    expect(config.version).toBe(1);
    expect(config.connection).toMatchObject({
      hasPlaintextKey: false,
      timeoutMs: 8000,
      maxConcurrency: 4,
      truncBudget: 32000,
    });
    expect(config.presets).toHaveLength(5);
    expect(config.presets.find((p) => p.id === "secret-leak")?.enabled).toBe(false);
    expect(config.history).toMatchObject({ perSession: 200, totalSessions: 50 });
  });
  it("每次返回新对象（不共享引用）", () => {
    const a = buildDefaultConfig();
    const b = buildDefaultConfig();
    expect(a).not.toBe(b);
    expect(a.presets).not.toBe(b.presets);
  });
});

describe("PUT 校验", () => {
  it("apiKeyRef 正则：小写/中文/空串拒收", () => {
    for (const bad of ["lower", "密钥", "", "a", "1ABC"]) {
      const r = validatePutBody({ apiKeyRef: bad });
      expect(r.ok).toBe(false);
    }
    expect(validatePutBody({ apiKeyRef: "JEV_API_KEY" }).ok).toBe(true);
  });
  it("双轨互斥：同传 400", () => {
    const r = validatePutBody({
      apiKeyRef: "JEV_API_KEY",
      apiKeyPlaintext: "Abcdefgh12345678",
      confirm: true,
    });
    expect(r.ok).toBe(false);
    if (!r.ok) expect(r.failure.errorCode).toBe("MUTUALLY_EXCLUSIVE");
  });
  it("明文免二次确认", () => {
    expect(validatePutBody({ apiKeyPlaintext: "Abcdefgh12345678" }).ok).toBe(true);
  });
  it("密钥形状拒收仅回类别", () => {
    const short = validatePutBody({ apiKeyPlaintext: "abc", confirm: true });
    expect(short.ok).toBe(false);
    if (!short.ok) {
      expect(short.failure.errorCode).toBe("INVALID_KEY_SHAPE");
      expect(short.failure.category).toBe("too-short");
      expect(JSON.stringify(short.failure)).not.toContain("abc");
    }
  });
  it("退役 baseUrl 与未知键 400", () => {
    const retired = validatePutBody({ baseUrl: "https://x" });
    expect(retired.ok).toBe(false);
    if (!retired.ok) expect(retired.failure.errorCode).toBe("RETIRED_KEY");
    const unknown = validatePutBody({ whatever: 1 });
    expect(unknown.ok).toBe(false);
    if (!unknown.ok) expect(unknown.failure.errorCode).toBe("UNKNOWN_KEY");
  });
  it("数值越界 400", () => {
    expect(validatePutBody({ timeoutMs: 1 }).ok).toBe(false);
    expect(validatePutBody({ maxConcurrency: 99 }).ok).toBe(false);
    expect(validatePutBody({ truncBudget: 50 }).ok).toBe(false);
  });
});

describe("落盘与版本", () => {
  it("VERSION 缺席即 0.0.0，写入后读回", () => {
    const home = tempHome();
    expect(readStoredVersion(home, deps())).toBe("0.0.0");
    writeStoredVersion(home, "0.1.0", deps());
    expect(readStoredVersion(home, deps())).toBe("0.1.0");
    expect(versionFile(home)).toContain("@wingsky-1/dsh-decision-gateway");
  });
  it("三文件独立命名空间目录", () => {
    const home = tempHome();
    expect(decisionGatewayHome(home)).toContain("@wingsky-1/dsh-decision-gateway");
    expect(configFile(home)).not.toBe(secretsFile(home));
    expect(secretsFile(home)).not.toBe(presetsFile(home));
  });
  it("退役键迁移剥离", () => {
    const { config, retired } = normalizeLoadedConfig({
      connection: { baseUrl: "x" },
      presets: [],
      history: {},
    });
    expect(retired).toContain("baseUrl");
    expect(config.version).toBe(1);
  });
  it("PUT 落盘后 GET 掩码（无原文）", () => {
    const home = tempHome();
    const checked = validatePutBody({ apiKeyPlaintext: "Abcdefgh12345678", confirm: true });
    expect(checked.ok).toBe(true);
    if (!checked.ok) return;
    const saved = savePatch(home, checked.patch, deps());
    expect(saved.config.connection.hasPlaintextKey).toBe(true);
    const masked = toMaskedConfig(saved);
    expect(JSON.stringify(masked)).not.toContain("Abcdefgh12345678");
    expect(masked.connection.hasPlaintextKey).toBe(true);
  });
  it("ENV 引用优先于明文", () => {
    const home = tempHome();
    const ref = validatePutBody({ apiKeyRef: "JEV_TEST_KEY_X1" });
    expect(ref.ok).toBe(true);
    if (!ref.ok) return;
    const saved = savePatch(home, ref.patch, deps());
    const resolved = resolveApiKey(saved, { JEV_TEST_KEY_X1: "EnvSecretValue12345" }, deps());
    expect(resolved).toMatchObject({ key: "EnvSecretValue12345", source: "env" });
    expect(resolveApiKey(saved, {}, deps()).source).toBe("none");
  });
});

/** BaseURL 防篡改：写死常量 + 退役键拒收 + 迁移剥离 + 出境 URL 精确（全离线）。
 *
 * 守的是 shared/contract.JEV_BASE_URL 与 config 退役键面：把基址改掉、PUT 放行 baseUrl、
 * 迁移漏剥任一改动，本文件必红。fetch 经注入捕获 URL，不触网。
 */
import { describe, expect, it } from "vitest";
import { normalizeLoadedConfig, validatePutBody } from "../../src/server/config/impl/model.ts";
import { decide } from "../../src/server/tools/impl/service.ts";
import type { DecideDeps } from "../../src/server/tools/deps.ts";
import { JEV_BASE_URL, JEV_MODEL } from "../../src/shared/contract.ts";

const EXPECTED_BASE = "https://api.typesafe.ai/v1/systemone";
const CONNECTION = {
  timeoutMs: 8000,
  maxConcurrency: 4,
  truncBudget: 32000,
  hasPlaintextKey: false,
} as const;

describe("BaseURL 写死", () => {
  it("常量即官方基址字面量（第二事实源手写）", () => {
    expect(JEV_BASE_URL).toBe(EXPECTED_BASE);
  });
  it("模型即冻结别名 jev-latest（与基址同等 pin 待遇）", () => {
    expect(JEV_MODEL).toBe("jev-latest");
  });
  // 注：退役键表成员由下条 PUT 逐键拒收断言覆盖（删表项即 UNKNOWN_KEY 而非 RETIRED_KEY），不另立表断言（去装饰）。
  it("PUT 遇退役键一律 RETIRED_KEY（顶层/connection/history 均拒）", () => {
    for (const key of ["baseUrl", "apiBaseUrl", "endpoint", "apiEndpoint", "url"]) {
      const r = validatePutBody({ [key]: "https://evil.example" });
      expect(r.ok).toBe(false);
      if (!r.ok) expect(r.failure.errorCode).toBe("RETIRED_KEY");
    }
    const nested = validatePutBody({ history: { perSession: 200, totalSessions: 50 } });
    expect(nested.ok).toBe(true);
  });
  it("加载迁移剥离退役键并告警名单", () => {
    const { config, retired } = normalizeLoadedConfig({
      connection: { baseUrl: "https://evil.example" },
      presets: [],
      history: {},
    });
    expect(retired).toContain("baseUrl");
    expect(config.version).toBe(1);
    expect(JSON.stringify(config)).not.toContain("evil.example");
  });
  it("出境 URL 精确等于基址（篡改即红）", async () => {
    let seenUrl = "";
    const deps: DecideDeps = {
      logger: { warn: () => {} },
      connection: { ...CONNECTION },
      isEnabled: () => true,
      capOf: () => 2,
      resolveKey: () => ({ key: "Abcdefgh12345678", source: "env" as const }),
      root: "/tmp/proj",
      sessionId: "sess-1",
      signal: new AbortController().signal,
      fetchImpl: async (url) => {
        seenUrl = url;
        return {
          status: 200,
          text: JSON.stringify({
            model: "jev-1.13.0",
            answers: {
              q1: {
                type: "choice",
                choice: "A",
                confidence: 0.9,
                probabilities: { A: 0.9, B: 0.1 },
              },
            },
            usage: { input_tokens: 9, output_tokens: 3 },
          }),
        };
      },
    };
    const out = await decide(
      {
        preset_id: "general",
        state: { text: "hi", lang: "en" },
        questions_override: [{ id: "q1", text: "Pick one.", kind: "choice", options: ["A", "B"] }],
      },
      deps,
    );
    expect(out.ok).toBe(true);
    expect(seenUrl).toBe(EXPECTED_BASE);
    expect(seenUrl).toBe(JEV_BASE_URL);
  });
});
